    10	/** Пауза после последнего символа перед записью поиска в URL. */
    11	export const SEARCH_DEBOUNCE_MS = 300;
    12	
    13	const SKELETON_ROWS = 5;
    14	
    15	interface SessionsPageProps {
    16	  /** Открывает форму создания (состояние открытости живёт в app). */
    17	  onCreateSession?: () => void;
    18	  /** Сигнал принудительного перезапроса списка (после создания сессии). */
    19	  reloadKey?: number;
    20	}
    21	
    22	function isStatus(value: string): value is SessionStatus {
    23	  return (SESSION_STATUSES as readonly string[]).includes(value);
    24	}
    25	
    26	export function SessionsPage({ onCreateSession, reloadKey = 0 }: SessionsPageProps) {
    27	  const { pathname, search } = useLocation();
    28	  const filters = readFilters(search);
    29	  const active = hasActiveFilters(filters);
    30	  const { status, data, error, isRefreshing, retry } = useSessions(filters, reloadKey);
    31	
    32	  // Локальное transient-значение поля; в URL уходит с debounce. Внешнее изменение URL
    33	  // (Назад, сброс) синхронизируется в поле во время рендера.
    34	  const [text, setText] = useState(filters.query);
    35	  const [seenQuery, setSeenQuery] = useState(filters.query);
    36	  if (seenQuery !== filters.query) {
    37	    setSeenQuery(filters.query);
    38	    if (filters.query !== text.trim()) setText(filters.query);
    39	  }
    40	  const [justCleared, setJustCleared] = useState(false);
    41	
    42	  const searchInput = useRef<HTMLInputElement>(null);
    43	  const timer = useRef<number | undefined>(undefined);
    44	  const latest = useRef({ pathname, search });
    45	  useEffect(() => {
    46	    latest.current = { pathname, search };
    47	  });
    48	  useEffect(() => () => window.clearTimeout(timer.current), []);
    49	
    50	  function replaceFilters(next: (search: string) => string): void {
    51	    const current = latest.current;
    52	    const nextSearch = next(current.search);
    53	    if (nextSearch === current.search) return;
    54	    navigate(`${current.pathname}${nextSearch}`, { replace: true, state: readHistoryState() });
    55	  }
    56	
    57	  function writeUpdate(update: FilterUpdate): void {
    58	    replaceFilters((s) => writeFilters(s, update));
    59	  }
    60	
    61	  function handleSearchChange(event: ChangeEvent<HTMLInputElement>): void {
    62	    const value = event.target.value;
    63	    setText(value);
    64	    setJustCleared(false);
    65	    window.clearTimeout(timer.current);
    66	    timer.current = window.setTimeout(() => writeUpdate({ query: value }), SEARCH_DEBOUNCE_MS);
    67	  }
    68	
    69	  function handleStatusChange(event: ChangeEvent<HTMLSelectElement>): void {
    70	    const value = event.target.value;
    71	    setJustCleared(false);
    72	    writeUpdate({ status: isStatus(value) ? value : "" });
    73	  }
    74	
    75	  function handleClear(): void {
    76	    window.clearTimeout(timer.current);
    77	    setText("");
    78	    setJustCleared(true);
    79	    // Фокус переносится до того, как кнопка исчезнет вместе с фильтрами.
    80	    searchInput.current?.focus();
    81	    replaceFilters(clearFilters);
    82	  }
    83	
    84	  const total = data?.meta.total ?? 0;
    85	  const rows = data?.data ?? [];
    86	
    87	  let liveMessage = "";
    88	  if (status === "loading") {
    89	    liveMessage = copy.loading;
    90	  } else if (status === "success") {
    91	    if (rows.length === 0) {
    92	      liveMessage = active ? copy.noMatchTitle : copy.emptyTitle;
    93	    } else if (justCleared) {
    94	      liveMessage = copy.filtersCleared(copy.sessionsCount(total));
    95	    } else {
    96	      liveMessage = active ? copy.matchCount(total) : copy.sessionsCount(total);
    97	    }
    98	  }
    99	
   100	  return (
   101	    <main className="page">
