   123	            type="search"
   124	            autoComplete="off"
   125	            spellCheck={false}
   126	            placeholder={copy.searchPlaceholder}
   127	            value={text}
   128	            onChange={handleSearchChange}
   129	          />
   130	        </div>
   131	        <div className="toolbar-status">
   132	          <label htmlFor="sessions-status" className="visually-hidden">
   133	            {copy.statusLabel}
   134	          </label>
   135	          <select
   136	            id="sessions-status"
   137	            name="status"
   138	            value={filters.status}
   139	            onChange={handleStatusChange}
   140	          >
   141	            <option value="">{copy.allStatuses}</option>
   142	            {SESSION_STATUSES.map((value) => (
   143	              <option key={value} value={value}>
   144	                {STATUS_LABELS[value]}
   145	              </option>
   146	            ))}
   147	          </select>
   148	        </div>
   149	        {active ? (
   150	          <button type="button" className="button button-secondary" onClick={handleClear}>
   151	            {copy.clearFilters}
   152	          </button>
   153	        ) : null}
   154	      </div>
   155	
   156	      <section className="list-area" aria-busy={isRefreshing}>
   157	        {status === "error" ? (
   158	          <div role="alert" className="state-message">
   159	            <h2>{copy.errorTitle}</h2>
   160	            <p>{copy.errorBody(error)}</p>
   161	            <button type="button" className="button button-primary" onClick={retry}>
   162	              {copy.tryAgain}
   163	            </button>
   164	          </div>
   165	        ) : null}
   166	
   167	        {status === "loading" && data === null ? (
   168	          <ul className="session-list" aria-hidden="true">
   169	            {Array.from({ length: SKELETON_ROWS }, (_, i) => (
   170	              <li key={i} className="session-row skeleton-row">
   171	                <span className="skeleton-line" />
   172	              </li>
   173	            ))}
   174	          </ul>
