   220	import { useCallback, useEffect, useState } from "react";
   221	import { getSessions } from "../../shared/api/client.ts";
   222	import type { ClientError } from "../../shared/api/errors.ts";
   223	import type { SessionsResponse } from "../../shared/api/types.ts";
   224	import type { SessionFilters } from "./filters.ts";
   225	
   226	export type SessionsStatus = "idle" | "loading" | "success" | "error";
   227	
   228	interface State {
   229	  status: SessionsStatus;
   230	  data: SessionsResponse | null;
   231	  error: ClientError | null;
   232	}
   233	
   234	interface Settled {
   235	  /** Ключ запроса, которому принадлежит результат. */
   236	  key: string;
   237	  data: SessionsResponse | null;
   238	  error: ClientError | null;
   239	}
   240	
   241	export interface UseSessionsResult extends State {
   242	  /** Идёт загрузка при уже имеющихся (прежних) данных: список приглушается. */
   243	  isRefreshing: boolean;
   244	  retry: () => void;
   245	}
   246	
   247	/**
   248	 * Список сессий по фильтрам. Запрос отменяется при смене фильтров и размонтировании, устаревшие
   249	 * ответы игнорируются. Прежние данные сохраняются на время `loading`. `reloadKey` — сигнал
   250	 * принудительного обновления (после создания сессии). Состояние `loading` выводится при рендере
   251	 * (ключ запроса не совпадает с ключом последнего результата), без setState в эффекте.
   252	 */
   253	export function useSessions(filters: SessionFilters, reloadKey = 0): UseSessionsResult {
   254	  const [settled, setSettled] = useState<Settled | null>(null);
   255	  const [attempt, setAttempt] = useState(0);
   256	  const { query, status } = filters;
   257	  const key = JSON.stringify([query, status, attempt, reloadKey]);
   258	
   259	  useEffect(() => {
   260	    const controller = new AbortController();
   261	    void getSessions({ query, status }, { signal: controller.signal }).then((result) => {
   262	      if (controller.signal.aborted) return;
   263	      if (result.ok) {
   264	        setSettled({ key, data: result.data, error: null });
   265	      } else if (!result.cancelled) {
   266	        setSettled({ key, data: null, error: result.error });
   267	      }
   268	    });
   269	    return () => controller.abort();
   270	  }, [key, query, status]);
   271	
   272	  const retry = useCallback(() => setAttempt((n) => n + 1), []);
   273	
   274	  if (settled !== null && settled.key === key) {
   275	    return {
   276	      status: settled.error === null ? "success" : "error",
   277	      data: settled.data,
   278	      error: settled.error,
   279	      isRefreshing: false,
   280	      retry,
   281	    };
   282	  }
   283	  const previous = settled?.data ?? null;
   284	  return { status: "loading", data: previous, error: null, isRefreshing: previous !== null, retry };
   285	}
}

.session-link {
  font-weight: 700;
  color: var(--text);
  text-decoration: none;
}

.session-link:hover,
.session-link:focus-visible {
  text-decoration: underline;
}

/* Фокус рисуется на всей строке (ссылка растянута на неё), а не на тексте названия. */
.session-link:focus-visible {
  outline: none;
}

.session-row:has(.session-link:focus-visible) {
  outline: 2px solid var(--focus);
  outline-offset: -2px;
}

/* Растянутая область клика на всю строку */
.session-link::after {
  content: "";
  position: absolute;
  inset: 0;
}

/* Бейдж статуса: иконка и текст */
.status-badge {
